```javascript
const auth = require('basic-auth');
const jwt = require('jsonwebtoken');

function authenticate(req, res, next) {
    const user = auth(req);
    if (!user || user.name !== 'admin' || user.pass !== 'securepassword') {
        return res.status(401).send('Unauthorized');
    }
    next();
}

// Use middleware for protected routes
app.get('/protected', authenticate, (req, res) => {
    res.json({ data: 'Secret information' });
});
```

---

### 7. **Missing Security Headers (MEDIUM)**
- **File**: `app.js`
- **Severity**: MEDIUM
- **Impact**: Various web application vulnerabilities

**Issue:** No security headers configured

**Recommendation:**
```javascript
const helmet = require('helmet');

// Helmet automatically sets various security headers
app.use(helmet());
// Custom headers
app.use((req, res, next) => {
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('X-Frame-Options', 'DENY');
    res.setHeader('X-XSS-Protection', '1; mode=block');
    res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
